// ListAccounts runs the :many query against sqlite.
func (q *sqliteQueries) ListAccounts(ctx context.Context, db DBTX, arg ListAccountsParams) ([]ListAccountsRow, error) {
	rows, err := db.QueryContext(ctx, q.listAccounts,
		arg.CreatedAfter,
		arg.CreatedBefore,
		arg.UpdatedAfter,
		arg.UpdatedBefore,
		arg.IncludeArchived,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListAccountsRow

	for rows.Next() {
		var i ListAccountsRow

		if err := rows.Scan(
			&i.ID,
			&i.Scope,
			&i.Name,
			&i.OwnerUserID,
			&i.BillingStatus,
			&i.SubscriptionPlanID,
			&i.PaymentProcessorCustomerID,
			&i.LastPaymentProviderSyncedAt,
			&i.AddressLine1,
			&i.AddressLine2,
			&i.AddressCity,
			&i.AddressState,
			&i.AddressPostalCode,
			&i.AddressCountry,
			&i.AddressPhone,
			&i.TimeZone,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

